 if(r.type==='plaza'){ctx.fillStyle='#6c7562';rr(ctx,r.x-7,r.y-7,r.w+14,r.h+14,11);ctx.fill();ctx.fillStyle='#8c9275';rr(ctx,r.x,r.y,r.w,r.h,8);ctx.fill();ctx.strokeStyle='#aab092';ctx.lineWidth=2;ctx.strokeRect(r.x+8,r.y+8,r.w-16,r.h-16);for(let n=0;n<3;n++){ctx.fillStyle='#495446';ctx.beginPath();ctx.arc(r.x+25+n*34,r.y+r.h/2,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#77876b';ctx.beginPath();ctx.arc(r.x+25+n*34,r.y+r.h/2-3,7,0,Math.PI*2);ctx.fill()}return}
