 const c=i%2?'#565b54':'#57534a';ctx.fillStyle=c;rr(ctx,r.x,r.y,r.w,r.h,5);ctx.fill();
 // rooftop segmented panels
 ctx.fillStyle=i%2?'#666a5e':'#625d51';rr(ctx,r.x+9,r.y+9,r.w-18,r.h-18,3);ctx.fill();
