 for(let k=0;k<3;k++){let x=r.x+27+k*((r.w-60)/3);ctx.fillStyle='#343c3b';rr(ctx,x,r.y+29,37,25,3);ctx.fill();ctx.fillStyle='#778079';ctx.fillRect(x+5,r.y+34,27,3);ctx.fillStyle='#414746';rr(ctx,x+12,r.y+r.h-54,48,30,3);ctx.fill()}
